CREATE TABLE IF NOT EXISTS access_keys(scope VARCHAR(20) CHARACTER SET ascii PRIMARY KEY, password_hash VARCHAR(300) NOT NULL, revision INT UNSIGNED NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS access_grants(token_hash CHAR(64) CHARACTER SET ascii NOT NULL, scope VARCHAR(20) CHARACTER SET ascii NOT NULL, expires_at DATETIME NOT NULL, PRIMARY KEY(token_hash,scope), INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS access_key_audit(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, scope VARCHAR(20) NOT NULL, revision INT NOT NULL, changed_at TIMESTAMP(6) DEFAULT CURRENT_TIMESTAMP(6)) ENGINE=InnoDB;
INSERT IGNORE INTO schema_version(version) VALUES(2);
